// tests/exporter-toHtml.test.ts
test("emits a complete standalone HTML document with headings and paragraphs", async () => {
  const html7 = await toHtml2("# Hello\n\nA paragraph of **bold** text.");
  assert.match(html7, /<!doctype html>/i);
  assert.match(html7, /<html[\s>]/i);
  assert.match(html7, /<body>/i);
  assert.match(html7, /<h1[^>]*>.*Hello.*<\/h1>/s);
  assert.match(html7, /A paragraph of/);
});
test("renders fenced code blocks", async () => {
  const html7 = await toHtml2("```js\nconst x = 1\n```");
  assert.match(html7, /<pre[ >]/);
  assert.match(html7, /<code[ >]/);
  assert.match(html7, /class="hljs language-js"/);
  assert.match(html7, /const/);
  assert.match(html7, /1/);
});
test("renders GFM tables", async () => {
  const md = "| Name | Age |\n| --- | --- |\n| Alice | 30 |\n| Bob | 25 |";
  const html7 = await toHtml2(md);
  assert.match(html7, /<table[ >]/);
  assert.match(html7, /<th[ >]/);
  assert.match(html7, /<td[ >]/);
  assert.match(html7, /Alice/);
  assert.match(html7, /Bob/);
});
test("pre-renders inline and block math via KaTeX (math-inline / math-block wrappers)", async () => {
  const html7 = await toHtml2("Inline $x^2$ and block:\n\n$$\\int_0^1 x\\,dx$$");
  assert.match(html7, /class="math-inline"/);
  assert.match(html7, /class="math-block"/);
  assert.match(html7, /katex/);
});
test("escapes the document title so it cannot inject markup", async () => {
  const html7 = await toHtml2("# ignored", "<script>alert(1)</script>");
  assert.doesNotMatch(html7, /<script>alert\(1\)<\/script>/);
  assert.match(html7, /<title>&lt;script&gt;alert\(1\)&lt;\/script&gt;<\/title>/);
});
test("inlines the KaTeX stylesheet so the file is offline-friendly", async () => {
  const html7 = await toHtml2("# x");
  assert.match(html7, /<style>/);
  assert.match(html7, /katex/i);
});
